    // BUG: loop bound is i * i < n instead of i * i <= n, so a perfect square
    // of a prime (4, 9, 25, 49, ...) is never divided by its own square root
    // and is wrongly reported as prime.
    for (long long i = 2; i * i < n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int main() {
    long long n;
    cin >> n;
    cout << (isPrime(n) ? "Prime" : "Not Prime") << endl;
    return 0;
}

